CREATE SCHEMA ouf_udp;
CREATE TABLE ouf_udp.resolution_review_package_confirmation(package_id uuid,tenant_id text,actor_subject text,confirmed_at timestamptz,authorization_decision_ref text);
CREATE TABLE ouf_udp.human_resolution_decision(decision_id uuid,issue_id uuid,action text,actor_subject text,authorization_decision_ref text,decided_at timestamptz);
CREATE TABLE ouf_udp.resolution_issue(issue_id uuid,handoff_id text,state text,tenant_id text,resolved_at timestamptz,resolved_by_subject text,authorization_decision_ref text);
CREATE TABLE ouf_udp.resolution_decision(handoff_id text,strategy_id text,outcome text,target_urban_object_id uuid);
CREATE TABLE ouf_udp.handoff_intake(handoff_id text,ingestion_run_id text,source_id text,type_code text,source_object_id text,state text,payload_json jsonb,raw_lake_object_id uuid);
CREATE TABLE ouf_udp.materialization_job(job_id uuid,handoff_id text,state text,state_version bigint,attempts int,integrity_attempts int,integrity_baseline_hash text,safe_failure_code text,claimed_by text,lease_until timestamptz);
CREATE TABLE ouf_udp.lake_object(lake_object_id uuid,state text,tenant_id text,source_id text,type_code text,tier text,access_label text);
CREATE TABLE ouf_udp.materialization_observation(handoff_id text);
CREATE TABLE ouf_udp.object_revision(source_handoff_id text);
CREATE TABLE ouf_udp.property_contribution(handoff_id text);
CREATE TABLE ouf_udp.source_binding(first_handoff_id text,source_id text,type_code text,source_object_id text);
CREATE TEMP TABLE fixture AS SELECT n,gen_random_uuid() issue,gen_random_uuid() decision,gen_random_uuid() job,gen_random_uuid() raw FROM generate_series(1,12)n;
INSERT INTO ouf_udp.resolution_review_package_confirmation VALUES('a5183503-04ff-4e10-850f-e22bf874365e','ouf-lab','b93d8cf6-cd14-4ee6-91d7-84cd76c4f500',transaction_timestamp(),'AUTH_NATIVE');
INSERT INTO ouf_udp.resolution_issue SELECT issue,'row-'||n,CASE WHEN n=12 THEN 'OPEN' ELSE 'RESOLVED' END,'ouf-lab',transaction_timestamp(),'b93d8cf6-cd14-4ee6-91d7-84cd76c4f500','AUTH_NATIVE'FROM fixture;
INSERT INTO ouf_udp.human_resolution_decision SELECT decision,issue,'CREATE_NEW','b93d8cf6-cd14-4ee6-91d7-84cd76c4f500','AUTH_NATIVE',transaction_timestamp()FROM fixture WHERE n<=11;
INSERT INTO ouf_udp.handoff_intake SELECT 'row-'||n,'fixture-run','teatri-csv-6609b245','THEATER','obj-'||n,'DURABLE','{"contractRefs":{"bundleRef":"PRIVATE_BUNDLE"},"canonicalPayload":{"name":"PRIVATE_OBJECT"}}',raw FROM fixture;
INSERT INTO ouf_udp.materialization_job SELECT job,'row-'||n,'QUARANTINED',12,1,5,'sha256:'||repeat('a',64),CASE WHEN n=12 THEN 'UDP_RESOLUTION_REVIEW_REQUIRED'ELSE 'UDP_REFERENCE_INTEGRITY_MISSING'END,null,null FROM fixture;
INSERT INTO ouf_udp.lake_object SELECT raw,'VERIFIED','ouf-lab','teatri-csv-6609b245','THEATER','RAW','OPEN'FROM fixture;
INSERT INTO ouf_udp.resolution_decision SELECT 'row-'||n,'GOVERNED_IDENTITY','REVIEW_REQUIRED',null FROM fixture;
CREATE SCHEMA ouf_authorization;
CREATE TABLE ouf_authorization.policy_bundle(bundle_id text,version bigint,bundle_payload jsonb);
CREATE TABLE ouf_authorization.active_policy_bundle(singleton_key boolean,bundle_id text,version bigint);
INSERT INTO ouf_authorization.policy_bundle VALUES('fixture',40,'{"capabilities":[{"capabilityId":"udp.materialization.retry","allowedActors":["HUMAN"],"operation":"COMMAND","requiredScope":"udp.materialization.retry"}],"grants":[{"capabilityId":"udp.materialization.retry","tenantId":"ouf-lab","subjectId":"b93d8cf6-cd14-4ee6-91d7-84cd76c4f500","validFrom":"2020-01-01T00:00:00Z","validUntil":"2099-01-01T00:00:00Z","constraints":{"effect":"ALLOW","resourceType":"materialization-job","resourceAttributes":{"module":"UDP"}}}]}');
INSERT INTO ouf_authorization.active_policy_bundle VALUES(true,'fixture',40);
